-- instr_rom.vhd : 256-word instruction ROM for MiniCPU-8
-- Program is passed as a generic constant INIT : rom_t (ascending, starting
-- at address 0) -- generated by tools/assembler.py. Words above the program
-- are filled with HALT (0xD000) so running off the end stops the CPU.
-- Asynchronous (combinational) read, as required by the single-cycle core.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.minicpu_pkg.all;

entity instr_rom is
  generic (
    INIT : rom_t);
  port (
    addr : in  byte_t;   -- 0..255
    data : out word_t);
end entity instr_rom;

architecture rtl of instr_rom is
  type mem_t is array (0 to 255) of word_t;

  function build return mem_t is
    variable m : mem_t := (others => HALT_WORD);
  begin
    for i in INIT'range loop
      m(i) := INIT(i);
    end loop;
    return m;
  end function;

  constant mem : mem_t := build;
begin
  -- The is_x guard keeps the simulator quiet during the very first delta
  -- cycle, before the PC register's output has settled from 'U'.
  read_p : process (addr) is
  begin
    if is_x(addr) then
      data <= HALT_WORD;
    else
      data <= mem(to_integer(unsigned(addr)));
    end if;
  end process;
end architecture rtl;
